onClick:
{{
  (async function() {
    const pageSource = appsmith.store.page_precedente;
    const idSource = appsmith.store.id_precedent;

    // Si on vient d'un de nos onglets Atelier (Global ou Perso)
    if (pageSource === '🛠️ Atelier Global' || pageSource === '🔨 Atelier Perso') {
      await navigateTo('🛠️ Atelier'); // IMPORTANT : c'est le nom de TA PAGE principale
    } 
    // Si on vient d'une autre page (Client, Facture, etc.)
    else if (pageSource && pageSource !== 'Détail Intervention') {
      if (idSource) {
        await navigateTo(pageSource, { id: idSource });
      } else {
        await navigateTo(pageSource);
      }
    } 
    // Sécurité au cas où rien n'est mémorisé
    else {
      await navigateTo('🛠️ Atelier');
    }
  })()
}}
